# Generated by manage.py generate_test_cases.
from bs4 import BeautifulSoup
from django.http import HttpResponse

from bloomerp.models.workspaces.sql_query import SqlQuery
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestSqlQueryView(BloomerpModelViewTestCase):
    """Tests class `SqlQueryView` from `bloomerp/views/workspaces/sql_query.py`."""

    view_name = 'query'
    model = SqlQuery

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Verify edge-to-edge rendering on full-page, HTMX, and history requests."""
        return [
            RequestScenario(
                name=name,
                user=self.admin_user,
                headers=headers,
                expected=ExpectedResult(response_validators=self.has_unpadded_editor),
            )
            for name, headers in (
                ("Full-page editor has no content padding", {}),
                ("HTMX navigation has no content padding", {"HX-Request": "true", "HX-Target": "main-content"}),
                ("History restoration has no content padding", {"HX-Request": "true", "HX-History-Restore-Request": "true"}),
            )
        ]

    def has_unpadded_editor(self, response: HttpResponse) -> bool:
        """Ensure the editor fills its parent without an outer frame or padding wrapper."""
        soup = BeautifulSoup(response.content, "html.parser")
        editor = soup.select_one('[bloomerp-component="sql-query-editor"]')
        if editor is None:
            return False
        classes = editor.get("class", [])
        return (
            "w-full" in classes
            and "min-w-0" in classes
            and "rounded-none" in classes
            and "border" not in classes
            and "p-4" not in editor.parent.get("class", [])
        )
